<script id="rampart-strategy">
function createStrategy() {
  const order = [[0,"bolt"],[1,"cannon"],[2,"lance"],[15,"flak"],[3,"lance"],[5,"flak"],[6,"cannon"],[7,"lance"],[4,"lance"],[8,"lance"],[10,"flak"],[11,"lance"],[12,"lance"],[9,"lance"],[13,"lance"],[14,"flak"]];
  const costs = {bolt:50,cannon:90,lance:120,flak:80};
  return {
    plan(s) {
      const actions = [];
      let gold = s.gold;
      const desired = order.map(([slot,type]) => ({slot,type,t:s.slots[slot].turret}));
      for (const {slot,type,t} of desired) {
        if (t) continue;
        if (gold < costs[type]) break;
        actions.push({op:"build",slot,type});
        gold -= costs[type];
      }
      if (desired.every(d => d.t)) {
        for (const tier of [1,2]) for (const {slot,type,t} of desired) {
          if (t.tier !== tier) continue;
          const cost = costs[type] * tier;
          if (gold < cost) return actions;
          actions.push({op:"upgrade",slot});
          gold -= cost;
        }
      }
      return actions;
    },
    target(t, candidates) {
      const damage = ({
        bolt:[26,41,65], cannon:[60,96,153], frost:[10,16,25],
        lance:[180,288,460], flak:[40,64,102]
      })[t.type][t.tier-1];
      const radius = t.type === "cannon" ? 8100 : t.type === "flak" ? 4900 : 0;
      let best = -Infinity, id = candidates[0].id;
      for (const e of candidates) {
        const hit = Math.max(1, damage - (t.type === "lance" ? 0 : e.armor));
        let value = Math.min(e.hp, hit) + (e.hp <= hit ? 16 : 0);
        if (e.type === "mender") value += 25;
        if (radius) for (const other of candidates) {
          if (other === e) continue;
          const dx = e.x-other.x, dy = e.y-other.y;
          if (dx*dx+dy*dy <= radius) {
            const splash = Math.max(1, damage-other.armor);
            value += Math.min(splash,other.hp) + (other.hp <= splash ? 12 : 0);
          }
        }
        value += 25 * (1-e.remaining/(e.air ? 2600 : 4600));
        if (e.remaining < 500) value += 160 * (1-e.remaining/500);
        if (value > best) {best = value; id = e.id;}
      }
      return id;
    }
  };
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const ground = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const air = [[0,6],[21,6],[21,11],[23,11]];
  const slots = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
    [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const types = ["bolt","cannon","frost","lance","flak"];
  const specs = [
    [50,26,8,300,0,0,false,true,true],[90,60,24,260,90,0,false,true,false],
    [70,10,12,240,0,30,false,true,true],[120,180,36,360,0,0,true,true,false],
    [80,40,10,320,70,0,false,false,true]
  ];
  const names = ["grunt","runner","wisp","brute","splitter","mender","splitling"];
  const foes = [[60,10,4,1,0,1,10],[40,20,4,1,0,2,4],[50,12,6,2,1,3,3],
    [150,6,9,3,0,4,3],[90,8,6,2,0,6,2],[70,8,7,2,0,8,1],[0,12,1,1,0,Infinity,0]];
  const floor = Math.floor;
  const strategy = createStrategy();
  // The replay supplies this callback on its local factory. The public result is unchanged.
  const record = createStrategy.record;
  const turrets = slots.map(() => null);
  let enemies = [], queue = [], queued = 0;
  let random = seed, wave = 0, gold = 250, baseHp = 10, uid = 0, fallTick = -1;
  const log = [], scaling = [0,1000];
  function draw() {
    random = (random + 0x6D2B79F5) | 0;
    let t = Math.imul(random ''^ (random >>> 15), 1 | random);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t;
    return (t ''^ (t >>> 14)) >>> 0;
  }
  function composition(w) {
    const available = foes.filter(f => f[5] <= w);
    const weight = available.reduce((sum,f) => sum+f[6],0);
    return Array.from({length:4+floor(3*w/5)}, () => {
      let r = draw()%weight;
      return available.findIndex(f => (r -= f[6]) < 0);
    });
  }
  let next = composition(1);
  function locate(e) {
    const route = e.air ? air : ground;
    let distance = e.progress;
    for (let i=1;i<route.length;i++) {
      const [x,y] = route[i-1], [nx,ny] = route[i];
      const length = 100*(Math.abs(nx-x)+Math.abs(ny-y));
      if (distance < length || i === route.length-1) {
        e.x = x*100+50 + Math.sign(nx-x)*distance;
        e.y = y*100+50 + Math.sign(ny-y)*distance;
        e.angle = Math.atan2(nx-x,ny-y);
        return;
      }
      distance -= length;
    }
  }
  function spawn(kind,w,progress=0,maxHp=floor(foes[kind][0]*scaling[w]/1000)) {
    const [,speed,bounty,leak,airborne] = foes[kind];
    const e = {id:++uid,kind,w,progress,maxHp,hp:maxHp,speed,bounty,leak,air:airborne,
      armor:kind===3 ? 6+w : kind===0 ? floor(w/4) : 0, slow:0, age:0};
    locate(e);
    enemies.push(e);
  }
  const length = e => e.air ? 2600 : 4600;
  function view(e) {
    return {id:e.id,type:names[e.kind],hp:e.hp,maxHp:e.maxHp,x:e.x,y:e.y,air:e.air,
      armor:e.armor,speed:e.speed,slowed:e.slow>0,remaining:length(e)-e.progress};
  }
  function within(e,x,y,r) {
    const dx=e.x-x, dy=e.y-y;
    return dx*dx+dy*dy<=r*r;
  }
  for (let tick=0; tick<maxTicks; tick++) {
    const effects = record ? [] : null;
    const begin = tick>=20 && (tick-20)%40===0;
    if (begin) {
      wave++;
      if (wave>1) scaling.push(floor(scaling[wave-1]*108/100));
      gold += Math.min(50,floor(gold*5/100))+10+2*wave;
      const current = next;
      next = composition(wave+1);
      const actions = strategy.plan({tick,wave,gold,baseHp,
        slots:slots.map(([x,y],slot) => {
          const t=turrets[slot];
          return {slot,x,y,turret:t ? {type:types[t.kind],tier:t.tier,spent:t.spent} : null};
        }), enemies:enemies.map(view),nextWave:next.map(k=>names[k])});
      if (record) effects.push(["wave",12,0]);
      for (const a of Array.isArray(actions) ? actions.slice(0,32) : []) {
        if (!a || !Number.isInteger(a.slot) || a.slot<0 || a.slot>=slots.length) continue;
        const s=a.slot, t=turrets[s], kind=types.indexOf(a.type);
        if (a.op==="build" && !t && kind>=0 && gold>=specs[kind][0]) {
          const cost=specs[kind][0];
          gold-=cost;
          turrets[s]={kind,tier:1,spent:cost,cooldown:0,damage:specs[kind][1]};
          log.push([tick,"B",s,kind]);
          if (record) effects.push(["build",slots[s][0]+.5,slots[s][1]+.5,kind]);
        } else if (a.op==="upgrade" && t && t.tier<3 && gold>=specs[t.kind][0]*t.tier) {
          const cost=specs[t.kind][0]*t.tier;
          gold-=cost;
          t.spent+=cost;
          t.damage=floor(t.damage*16/10);
          log.push([tick,"U",s,++t.tier]);
          if (record) effects.push(["upgrade",slots[s][0]+.5,slots[s][1]+.5,t.kind]);
        } else if (a.op==="sell" && t) {
          gold+=floor(t.spent*70/100);
          turrets[s]=null;
          log.push([tick,"S",s,0]);
          if (record) effects.push(["sell",slots[s][0]+.5,slots[s][1]+.5,t.kind]);
        }
      }
      queue = queue.slice(queued);
      queued = 0;
      current.forEach((kind,i)=>queue.push({tick:tick+4*i,w:wave,i,kind}));
      queue.sort((a,b)=>a.tick-b.tick || a.w-b.w || a.i-b.i);
    }
    while (queued<queue.length && queue[queued].tick===tick) {
      const {kind,w}=queue[queued++];
      spawn(kind,w);
    }
    const leaked = new Set();
    for (const e of enemies) {
      e.progress+=e.slow ? floor(e.speed*60/100) : e.speed;
      if (e.progress>=length(e)) {
        leaked.add(e.id);
        baseHp-=e.leak;
        log.push([tick,"L",e.id,baseHp]);
        if (record) effects.push(["leak",23.5,11.5,baseHp]);
        if (baseHp<=0) {
          fallTick=tick;
          log.push([tick,"F",wave,0]);
          if (record) effects.push(["fall",23.5,11.5]);
          break;
        }
      } else locate(e);
    }
    if (leaked.size) enemies=enemies.filter(e=>!leaked.has(e.id));
    if (fallTick<0) {
      for (const e of enemies) {
        e.age++;
        if (e.kind!==5 || e.age%20!==0) continue;
        for (const other of enemies) if (within(other,e.x,e.y,150)) {
          other.hp=Math.min(other.maxHp,other.hp+floor(other.maxHp*8/100));
        }
        if (record) effects.push(["heal",e.x/100,e.y/100]);
      }
      for (let slot=0;slot<slots.length;slot++) {
        const t=turrets[slot];
        if (!t || (t.cooldown>0 && --t.cooldown>0)) continue;
        const [, ,period,baseRange,splash,slow,pierce,groundHit,airHit]=specs[t.kind];
        const x=slots[slot][0]*100+50, y=slots[slot][1]*100+50;
        const range=baseRange+30*(t.tier-1);
        const domain=e=>e.air ? airHit : groundHit;
        const candidates=enemies.filter(e=>domain(e)&&within(e,x,y,range));
        if (!candidates.length) continue;
        const selected=strategy.target?.({slot,type:types[t.kind],tier:t.tier,x,y,range},candidates.map(view));
        const target=candidates.find(e=>e.id===selected) ||
          candidates.reduce((best,e)=>length(e)-e.progress<length(best)-best.progress ? e : best);
        if (record) effects.push(["shot",x/100,y/100,t.kind,target.x/100,target.y/100,target.air,slot]);
        const victims=splash ? enemies.filter(e=>domain(e)&&within(e,target.x,target.y,splash)) : [target];
        for (const e of victims) {
          e.hp-=Math.max(1,t.damage-(pierce ? 0 : e.armor));
          if (slow) e.slow=slow;
        }
        t.cooldown=period;
        const dead=enemies.filter(e=>e.hp<=0);
        if (dead.length) {
          enemies=enemies.filter(e=>e.hp>0);
          for (const e of dead) {
            gold+=e.bounty;
            log.push([tick,"K",e.id,slot]);
            if (record) effects.push(["kill",e.x/100,e.y/100,e.kind]);
            if (e.kind===4) for (let i=0;i<3;i++) spawn(6,e.w,e.progress,Math.max(1,floor(e.maxHp/4)));
          }
        }
      }
      for (const e of enemies) if (e.slow>0) e.slow--;
    }
    if (record) record(tick,{wave,gold,baseHp,next:next.slice(),effects,
      turrets:turrets.map(t=>t && [t.kind,t.tier]),
      enemies:enemies.map(e=>[e.id,e.kind,e.x/100,e.y/100,e.hp/e.maxHp,e.angle,e.slow>0])});
    if (fallTick>=0) break;
  }
  let hash=0x811c9dc5;
  const serialized=JSON.stringify(log);
  for (let i=0;i<serialized.length;i++) hash=Math.imul(hash''^serialized.charCodeAt(i),0x01000193);
  return {score:Number((((fallTick<0 ? maxTicks : fallTick)-20)/40).toFixed(2)),
    fallTick,log,hash:(hash>>>0).toString(16).padStart(8,"0")};
}
</script>
