      setState("PLAYING");
      advance(countdownElapsed-3);
    }else{
      countdown.style.display="block";
      countdown.textContent=String(3-Math.floor(countdownElapsed));
    }
  }else if(state==="REFIRE_HOLD"){
    holdElapsed+=dt;
    if(holdElapsed>=1){
      setState("PLAYING");
      advance(holdElapsed-1);
    }
  }else if(state==="PLAYING")advance(dt);
  if(simTime!==lastDrawn){
    if(run.fallTick<0||simTime<run.fallTick/20+1.8||lastDrawn<run.fallTick/20+1.8)show(simTime);
  }
  requestAnimationFrame(update);
}
toggle.addEventListener("click",()=>{
  lastWall=performance.now();
  if(state==="PLAYING"||state==="COUNTDOWN"||state==="REFIRE_HOLD"){
    setState("PAUSED");
  }else{
    if(state==="ENDED"){
      simTime=0;
      scrubber.value="0";
      show(0);
    }
    setState("PLAYING");
  }
});
refire.addEventListener("click",()=>{
  lastWall=performance.now();
  simTime=0;
  holdElapsed=0;
  scrubber.value="0";
  setState("REFIRE_HOLD");
  show(0);
});
for(const pill of pills)pill.addEventListener("click",()=>{
  playbackSpeed=Number(pill.dataset.speed);
  for(const candidate of pills){
    candidate.classList.toggle("is-active",candidate===pill);
    candidate.setAttribute("aria-checked",String(candidate===pill));
  }
});
scrubber.addEventListener("pointerdown",()=>{
  dragging=true;
  audio.active(false);
});
for(const signal of ["pointerup","pointercancel"])window.addEventListener(signal,()=>{
  dragging=false;
  audio.active(state==="PLAYING");
});
scrubber.addEventListener("input",()=>{
  setState("PAUSED");
  simTime=Number(scrubber.value);
  show(simTime);
});
requestAnimationFrame(update);
})();
