/bin/zsh -c "printf %s 'function createStrategy() {
  const types = [\"bolt\",\"cannon\",\"frost\",\"lance\",\"flak\"];
  const cost = {bolt:50,cannon:90,frost:70,lance:120,flak:80};
  const damage = {bolt:[26,41,65],cannon:[60,96,153],frost:[10,16,25],
    lance:[180,288,460],flak:[40,64,102]};
  const initial = [0,0,1,1,1,4,1,1,4,1,1,1,0,0,4,0].map(i=>types[i]);
  // Orders are slot + 16 * current tier. Purchases at bends earn bounties early,
  // while the air batteries cover the second half of the lane as HP scales.
  const priorities = [
    39,15,1,0,3,38,22,26,21,33,8,42,11,16,6,4,14,12,47,35,19,17,18,13,
    23,2,7,5,29,31,30,25,40,9,24,32,20,28,27,37,34,43,44,36,45,41,10,46
  ];
  const refits = [[15,\"cannon\",23],[13,\"flak\",42]];
  return {
    plan(s) {
      const actions=[];
      const tiers=s.slots.map(slot=>slot.turret?.tier||0);
      const built=s.slots.map(slot=>slot.turret?.type||initial[slot.slot]);
      let gold=s.gold, reserved=0;
      for(const [slot,type,wave] of refits){
        const turret=s.slots[slot].turret;
        if(s.wave<wave||"'!turret||turret.type===type)continue;
        const refund=Math.floor(turret.spent*70/100);
        const price=cost[type]*2;
        if(gold+refund<price)continue;
        actions.push({op:"sell",slot},{op:"build",slot,type},{op:"upgrade",slot});
        tiers[slot]=2;
        built[slot]=type;
        gold+=refund-price;
      }
      for(const move of priorities){
        const slot=move%16, tier=Math.floor(move/16);
        if(tiers[slot]!==tier)continue;
        const type=built[slot], price=cost[type]*Math.max(1,tier);
        if(gold<price){
          reserved=Math.max(reserved,price*.6);
          continue;
        }
        if(gold-price<reserved)continue;
        actions.push(tier ? {op:"upgrade",slot} : {op:"build",slot,type});
        gold-=price;
        tiers[slot]++;
      }
      return actions;
    },
    target(t,candidates) {
      const power=damage[t.type][t.tier-1];
      const radius=t.type==="cannon" ? 8100 : t.type==="flak" ? 4900 : 0;
      let best=-Infinity, id=candidates[0].id;
      for(const e of candidates){
        const hit=Math.max(1,power-(t.type==="lance" ? 0 : e.armor));
        let value=Math.min(e.hp,hit)+(e.hp<=hit ? 30 : 0);
        if(e.type==="mender")value+=25;
        if(radius)for(const other of candidates){
          if(other===e)continue;
          const dx=e.x-other.x, dy=e.y-other.y;
          if(dx*dx+dy*dy<=radius)value+=Math.min(Math.max(1,power-other.armor),other.hp);
        }
        value+=43*(1-e.remaining/(e.air ? 2800 : 4600));
        if(e.remaining<500)value+=260*(1-e.remaining/500);
        if(value>best){best=value;id=e.id;}
      }
      return id;
    }
  };
}
'"' > ../tmp/final-strategy.js"

