/bin/zsh -c "printf %s 'const selected=policies[8];
const ss=[9013,192137,56117,735743,9771,33];
function mean(p) {
  const f=factory(p);
  const s=ss.map(k=>rampartSimulate(f,k,3000).score);
  return s.reduce((a,b)=>a+b,0)/s.length;
}
let champion=[mean(selected),selected];
print(champion[0],JSON.stringify(champion[1]));
for(let j=0;j<3;j++){
  const queue=[champion[1]];
  for(const type of [1,2,3,4])for(let slot=0;slot<16;slot++)for(const w of [14,23,31,37,42,46]){
    const candidate=JSON.parse(JSON.stringify(champion[1]));
    const current=candidate.switches.find(x=>x[0]===slot)?.[1]??candidate.types[slot];
    if(current===type)continue;
    candidate.switches=candidate.switches.filter(x=>x[0]"'!==slot);
    candidate.switches.push([slot,type,w]);
    queue.push(candidate);
  }
  let best=champion;
  for(const p of queue){
    const value=mean(p);
    if(value>best[0]){best=[value,p];print(value,JSON.stringify(p));}
  }
  if(best===champion)break;
  champion=best;
}
'"' > ../tmp/step3.js"

